import{_ as t,c as r,o as n,ae as i}from"./chunks/framework.Bw0Gm4PQ.js";const m=JSON.parse('{"title":"EXCLUSIONS FROM FEDERAL LABOR-MANAGEMENT RELATIONS PROGRAMS","description":"","frontmatter":{"title":"EXCLUSIONS FROM FEDERAL LABOR-MANAGEMENT RELATIONS PROGRAMS","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/03/exclusions-from-federal-labor-management-relations-programs/","publishDate":"2025-03-27T22:07:43-04:00"},"headers":[],"relativePath":"executive-orders/2025-03-28-exclusions-from-federal-labor-management-relations-programs.md","filePath":"executive-orders/2025-03-28-exclusions-from-federal-labor-management-relations-programs.md"}'),a={name:"executive-orders/2025-03-28-exclusions-from-federal-labor-management-relations-programs.md"};function o(s,e,l,u,g,d){return n(),r("div",null,e[0]||(e[0]=[i('<h1 id="exclusions-from-federal-labor-management-relations-programs" tabindex="-1">EXCLUSIONS FROM FEDERAL LABOR-MANAGEMENT RELATIONS PROGRAMS <a class="header-anchor" href="#exclusions-from-federal-labor-management-relations-programs" aria-label="Permalink to &quot;EXCLUSIONS FROM FEDERAL LABOR-MANAGEMENT RELATIONS PROGRAMS&quot;">​</a></h1><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/03/exclusions-from-federal-labor-management-relations-programs/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/03/exclusions-from-federal-labor-management-relations-programs/</a></p><p>Published: Thursday, March 27, 2025</p><ul><li><p><strong>Authority</strong>: The President issues the order under the Constitution and U.S. laws to enhance national security.</p></li><li><p><strong>Agencies Involved</strong>:</p><ul><li>Section 2 agencies are primarily focused on intelligence, counterintelligence, investigative, or national security work and are exempt from Chapter 71 of title 5 regarding labor-management relations.</li><li>Section 3 subdivisions also focus on similar functions and are exempt from Subchapter X of Chapter 52 of title 22.</li></ul></li><li><p><strong>Amendments to Executive Order 12171</strong>:</p><ul><li>Changes include updates on which departments and subdivisions are involved in national security work.</li></ul></li><li><p><strong>Departments and Subdivisions Listed</strong>:</p><ul><li><strong>Department of State</strong>, <strong>Department of Defense</strong>, <strong>Department of the Treasury</strong>, <strong>Department of Veterans Affairs</strong>, <strong>Department of Justice</strong>, among others, are defined as having a primary function related to national security.</li><li>Specific subdivisions within agencies like the Department of Health and Human Services, Department of Homeland Security, Department of Interior, and others are also detailed.</li></ul></li><li><p><strong>Suspension Authority</strong>:</p><ul><li>Secretaries of Defense and Veterans Affairs can suspend application of certain executive order sections if consistent with national security.</li></ul></li><li><p><strong>Transportation Sector</strong>:</p><ul><li>The Secretary of Transportation is given authority to exclude subdivisions from coverage under federal labor-management statutes for operational flexibility.</li></ul></li><li><p><strong>Termination Measures</strong>:</p><ul><li>Agencies must reassign employees previously in bargaining units to agency-related duties and withdraw from any ongoing grievance proceedings once collective bargaining agreements terminate.</li></ul></li><li><p><strong>Reporting Requirement</strong>:</p><ul><li>Agency heads must report any subdivisions not covered by the order but engaged in national security work within 30 days.</li></ul></li><li><p><strong>General Provisions</strong>:</p><ul><li>The order does not alter existing legal authorities of departments or the functions of the Office of Management and Budget.</li><li>The order does not create enforceable rights against the U.S. or its entities.</li></ul></li></ul>',4)]))}const p=t(a,[["render",o]]);export{m as __pageData,p as default};
